"""The book file: a SQLite database with numbered schema versions."""
import json
import os
import re
import sqlite3
from contextlib import contextmanager
from dataclasses import dataclass, field, replace
from datetime import date, timedelta

from tallybook import budgets as _budgets
from tallybook import csvimport as _csvimport
from tallybook import recurring as _recurring
from tallybook.accounts import TYPES, Chart, ChartError
from tallybook.currency import CurrencyError, RateTable, currency
from tallybook.dates import format_date, is_date, parse_date
from tallybook.errors import ConflictError, NotFoundError, ValidationError
from tallybook.export import money_to_dict, transaction_to_dict, transactions_from_json
from tallybook.journal import Journal
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money
from tallybook.query import Query, parse_query
from tallybook.rules import RuleSet, parse_rules

LATEST_VERSION = 4

_PROFILE_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS = re.compile(r"[A-Za-z0-9_-]+")
_LETTERS3 = re.compile(r"[A-Za-z]{3}")


@dataclass
class BulkAdd:
    added: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: list = field(default_factory=list)
    duplicates: list = field(default_factory=list)
    errors: list = field(default_factory=list)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


# -- schema steps -------------------------------------------------------------


def _step_1(conn):
    conn.execute(
        "CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT, "
        "note TEXT NOT NULL DEFAULT '')"
    )
    conn.execute(
        "CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, payee TEXT NOT NULL, "
        "narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)"
    )
    conn.execute(
        "CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT, "
        "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
        "seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path), "
        "minor INTEGER NOT NULL, currency TEXT NOT NULL)"
    )
    conn.execute("CREATE INDEX transactions_date ON transactions(date, id)")
    conn.execute("CREATE INDEX postings_tx ON postings(tx_id, seq)")


def _step_2(conn):
    bad = conn.execute("SELECT COUNT(*) FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)").fetchone()[0]
    if bad:
        raise ValueError("%d transactions have a cleared value that is not 0 or 1" % bad)
    conn.execute(
        "CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
        "tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))"
    )
    conn.execute("ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'")
    conn.execute("ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''")
    conn.execute("UPDATE transactions SET flag = CASE WHEN cleared = 1 THEN '*' ELSE '!' END")


def _clean_currency(text):
    if text is None:
        return None
    cleaned = text.strip()
    if cleaned == "":
        return None
    if _LETTERS3.fullmatch(cleaned) is None:
        raise ValueError("bad currency %r" % (text,))
    return cleaned.upper()


def _step_3(conn):
    conn.execute(
        "CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL, rate_text TEXT NOT NULL, "
        "PRIMARY KEY (src, dst, on_date))"
    )
    conn.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")
    for path, cur in conn.execute("SELECT path, currency FROM accounts").fetchall():
        new = _clean_currency(cur)
        if new != cur:
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (new, path))
    for pid, cur in conn.execute("SELECT id, currency FROM postings").fetchall():
        new = _clean_currency(cur)
        if new is None:
            raise ValueError("posting %d has an empty currency" % pid)
        if new != cur:
            conn.execute("UPDATE postings SET currency = ? WHERE id = ?", (new, pid))


def _step_4(conn):
    conn.execute(
        "CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL, "
        "currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))"
    )
    conn.execute(
        "CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL, "
        "start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)"
    )
    conn.execute("CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)")
    conn.execute("CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
    conn.execute(
        "CREATE TABLE import_keys (key TEXT PRIMARY KEY, "
        "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)"
    )


_STEPS = {1: _step_1, 2: _step_2, 3: _step_3, 4: _step_4}


def _sort_key(path):
    return tuple(path.split(":"))


class Store:
    def __init__(self, conn, path):
        self._conn = conn
        self.path = path
        self._closed = False

    # -- opening ----------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        path = os.fspath(path)
        if isinstance(path, bytes):
            path = os.fsdecode(path)
        if os.path.isdir(path):
            raise ConflictError("%s is a directory, not a tallybook book" % path)
        exists = os.path.exists(path)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s (run `tallybook init`)" % path)
            parent = os.path.dirname(os.path.abspath(path))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
        try:
            conn = sqlite3.connect(path, timeout=5.0, isolation_level=None, check_same_thread=False)
        except sqlite3.Error as exc:
            raise ConflictError("cannot open %s: %s" % (path, exc)) from None
        try:
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT COUNT(*) FROM sqlite_master").fetchone()[0]
            conn.execute("PRAGMA foreign_keys = ON")
        except sqlite3.Error as exc:
            conn.close()
            raise ConflictError("%s is not a tallybook book: %s" % (path, exc)) from None
        if version == 0 and tables > 0:
            conn.close()
            raise ConflictError("%s is a SQLite database but not a tallybook book" % path)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError(
                "%s is at schema version %d, newer than this program understands (%d)" % (path, version, LATEST_VERSION)
            )
        store = cls(conn, path)
        if create and version == 0:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        if not self._closed:
            self._closed = True
            try:
                self._conn.close()
            except sqlite3.Error:
                pass

    # -- plumbing ---------------------------------------------------------
    def _alive(self):
        if self._closed:
            raise ConflictError("the book is closed")

    @property
    def version(self):
        self._alive()
        return self._conn.execute("PRAGMA user_version").fetchone()[0]

    def _current(self):
        self._alive()
        version = self.version
        if version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)

    @contextmanager
    def _write(self):
        self._current()
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise ConflictError("database is busy: %s" % exc) from None
        try:
            yield conn
        except sqlite3.Error as exc:
            self._rollback()
            raise ConflictError("database error: %s" % exc) from None
        except BaseException:
            self._rollback()
            raise
        else:
            try:
                conn.execute("COMMIT")
            except sqlite3.Error as exc:
                self._rollback()
                raise ConflictError("database is busy: %s" % exc) from None

    def _rollback(self):
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass

    @contextmanager
    def _read(self):
        self._current()
        conn = self._conn
        try:
            conn.execute("BEGIN")
        except sqlite3.Error as exc:
            raise ConflictError("database is busy: %s" % exc) from None
        try:
            yield conn
        except sqlite3.Error as exc:
            raise ConflictError("database error: %s" % exc) from None
        finally:
            self._rollback()

    # -- migrations -------------------------------------------------------
    def migrate(self):
        self._alive()
        applied = []
        conn = self._conn
        for target in range(self.version + 1, LATEST_VERSION + 1):
            try:
                conn.execute("BEGIN IMMEDIATE")
            except sqlite3.Error as exc:
                raise ConflictError("migration to version %d failed: %s" % (target, exc)) from None
            try:
                _STEPS[target](conn)
                conn.execute("PRAGMA user_version = %d" % target)
                conn.execute("COMMIT")
            except Exception as exc:
                self._rollback()
                raise ConflictError("migration to version %d failed: %s" % (target, exc)) from None
            applied.append(target)
        return applied

    # -- accounts ---------------------------------------------------------
    @staticmethod
    def _account(row):
        path, type_, currency, opened, note, closed = row
        return Account(
            path,
            type_,
            currency,
            parse_date(opened) if opened else None,
            parse_date(closed) if closed else None,
            note,
        )

    def _account_rows(self):
        rows = self._conn.execute("SELECT path, type, currency, opened, note, closed FROM accounts").fetchall()
        accounts = [self._account(r) for r in rows]
        accounts.sort(key=lambda a: _sort_key(a.path))
        return accounts

    def _chart(self):
        chart = Chart()
        for a in self._account_rows():
            try:
                chart.add(a.path, a.type, a.currency, a.opened, a.note)
            except ChartError:
                chart._accounts[a.path] = Account(a.path, a.type, a.currency, a.opened, None, a.note)
                chart._explicit.add(a.path)
            chart._accounts[a.path].closed = a.closed
        return chart

    def _rate_table(self):
        table = RateTable()
        for src, dst, on, text in self._conn.execute(
            "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date"
        ):
            table.set(src, dst, text, parse_date(on))
        return table

    def chart(self):
        with self._read():
            return self._chart()

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._write() as conn:
            chart = self._chart()
            account = chart.add(path, type, currency, opened, note)
            conn.execute(
                "INSERT INTO accounts(path, type, currency, opened, note, closed) VALUES (?, ?, ?, ?, ?, NULL)",
                (account.path, account.type, account.currency, _d(account.opened), account.note),
            )
            return replace(account)

    def _stored_account(self, path):
        if not isinstance(path, str):
            raise NotFoundError("no such account: %s" % (path,))
        row = self._conn.execute(
            "SELECT path, type, currency, opened, note, closed FROM accounts WHERE path = ?", (path,)
        ).fetchone()
        if row is None:
            raise NotFoundError("no such account: %s" % path)
        return self._account(row)

    def get_account(self, path):
        with self._read():
            return self._stored_account(path)

    def _filtered_accounts(self, type, under, currency, include_closed):
        if type is not None and type not in TYPES:
            raise ValidationError("unknown account type %r" % (type,))
        out = []
        for a in self._account_rows():
            if type is not None and a.type != type:
                continue
            if under is not None and not (a.path == under or a.path.startswith(str(under) + ":")):
                continue
            if currency is not None and a.currency != currency:
                continue
            if not include_closed and a.closed is not None:
                continue
            out.append(a)
        return out

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._read():
            return self._filtered_accounts(type, under, currency, include_closed)

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type, under, currency, include_closed))

    def close_account(self, path, on):
        with self._write() as conn:
            self._stored_account(path)
            chart = self._chart()
            chart.close(path, on)
            latest = conn.execute(
                "SELECT MAX(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id WHERE p.account = ?",
                (path,),
            ).fetchone()[0]
            if latest is not None and latest > format_date(on):
                raise ConflictError("cannot close %s on %s: it has a posting on %s" % (path, format_date(on), latest))
            conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
            return self._stored_account(path)

    def set_account_note(self, path, note):
        if not isinstance(note, str):
            raise ValidationError("note must be text")
        with self._write() as conn:
            self._stored_account(path)
            conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            return self._stored_account(path)

    def delete_account(self, path):
        with self._write() as conn:
            self._stored_account(path)
            used = conn.execute("SELECT COUNT(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]
            if used:
                raise ConflictError("account %s has postings and cannot be deleted" % path)
            conn.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # -- transactions -----------------------------------------------------
    def _assemble(self, rows):
        txs = []
        by_id = {}
        for tid, d, payee, narration, flag in rows:
            tx = Transaction(parse_date(d), payee, narration, [], (), flag, tid)
            txs.append(tx)
            by_id[tid] = tx
        ids = list(by_id)
        tags = {}
        for i in range(0, len(ids), 500):
            chunk = ids[i : i + 500]
            marks = ",".join("?" * len(chunk))
            for tid, account, minor, cur, note in self._conn.execute(
                "SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) ORDER BY tx_id, seq"
                % marks,
                chunk,
            ):
                by_id[tid].postings.append(Posting(account, Money(minor, cur), note))
            for tid, tag in self._conn.execute("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, chunk):
                tags.setdefault(tid, []).append(tag)
        for tid, lst in tags.items():
            by_id[tid].tags = tuple(sorted(lst))
        return txs

    def _tx_rows(self, where="", params=(), limit=None, offset=0):
        sql = "SELECT id, date, payee, narration, flag FROM transactions %s ORDER BY date, id" % where
        if limit is not None or offset:
            sql += " LIMIT ? OFFSET ?"
            params = tuple(params) + (-1 if limit is None else limit, offset)
        return self._conn.execute(sql, params).fetchall()

    def _query_obj(self, query, chart=None):
        if query is None:
            return None
        if isinstance(query, Query):
            return None if query.is_empty else query
        if not isinstance(query, str):
            raise ValidationError("query must be text or a Query, got %r" % (query,))
        if query.strip() == "":
            return None
        return parse_query(query, chart if chart is not None else self._chart())

    @staticmethod
    def _paging(limit, offset):
        if limit is not None and (not _is_int(limit) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0, got %r" % (limit,))
        if not _is_int(offset) or offset < 0:
            raise ValidationError("offset must be a whole number of at least 0, got %r" % (offset,))

    def _matching(self, query):
        q = self._query_obj(query)
        txs = self._assemble(self._tx_rows())
        if q is not None:
            txs = [t for t in txs if q.matches(t)]
        return txs

    def transactions(self, query=None, limit=None, offset=0):
        self._paging(limit, offset)
        with self._read():
            q = self._query_obj(query)
            if q is None:
                return self._assemble(self._tx_rows(limit=limit, offset=offset))
            txs = [t for t in self._assemble(self._tx_rows()) if q.matches(t)]
            txs = txs[offset:]
            return txs if limit is None else txs[:limit]

    def count_transactions(self, query=None):
        with self._read():
            q = self._query_obj(query)
            if q is None:
                return self._conn.execute("SELECT COUNT(*) FROM transactions").fetchone()[0]
            return sum(1 for t in self._assemble(self._tx_rows()) if q.matches(t))

    def has_import_key(self, key):
        with self._read():
            return self._conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    def _get_tx(self, id):
        if not _is_int(id):
            raise NotFoundError("no transaction %s" % (id,))
        rows = self._tx_rows("WHERE id = ?", (id,))
        if not rows:
            raise NotFoundError("no transaction %s" % id)
        return self._assemble(rows)[0]

    def get_transaction(self, id):
        with self._read():
            return self._get_tx(id)

    def delete_transaction(self, id):
        with self._write() as conn:
            tx = self._get_tx(id)
            for table in ("import_keys", "tags", "postings"):
                conn.execute("DELETE FROM %s WHERE tx_id = ?" % table, (id,))
            conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
            return tx

    def _insert(self, conn, tx):
        cur = conn.execute(
            "INSERT INTO transactions(date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
            (format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0, tx.flag),
        )
        tid = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            conn.execute(
                "INSERT INTO postings(tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                (tid, seq, p.account, p.amount.minor, p.amount.currency, p.note),
            )
        for tag in tx.tags:
            conn.execute("INSERT INTO tags(tx_id, tag) VALUES (?, ?)", (tid, tag))
        return replace(tx, id=tid)

    def _validated(self, ledger, tx):
        if isinstance(tx, Transaction):
            tx = replace(tx, id=None)
        return ledger.add(tx)

    def add_transaction(self, tx):
        with self._write() as conn:
            ledger = Ledger(self._chart(), self._rate_table())
            return self._insert(conn, self._validated(ledger, tx))

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or any(not isinstance(k, str) for k in keys):
                raise ValidationError("keys must hold one text per transaction")
        result = BulkAdd()
        with self._write() as conn:
            ledger = Ledger(self._chart(), self._rate_table())
            seen = set()
            for index, tx in enumerate(txs):
                key = None if keys is None else keys[index]
                if key is not None and (
                    key in seen or conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone()
                ):
                    result.skipped.append(index)
                    continue
                try:
                    stored = self._insert(conn, self._validated(ledger, tx))
                except ValidationError as exc:
                    exc.detail = dict(exc.detail, index=index)
                    raise
                if key is not None:
                    seen.add(key)
                    conn.execute("INSERT INTO import_keys(key, tx_id) VALUES (?, ?)", (key, stored.id))
                result.added.append(stored)
        return result

    def ledger(self):
        with self._read():
            ledger = Ledger(self._chart(), self._rate_table())
            for tx in self._assemble(self._tx_rows()):
                ledger.add(tx)
            return ledger

    # -- rates, budgets, recurring ----------------------------------------
    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        with self._write() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO rates(src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                (src, dst, format_date(on), rate_text),
            )

    def remove_rate(self, src, dst, on):
        currency(src)
        currency(dst)
        if not is_date(on):
            raise CurrencyError("date must be a datetime.date, got %r" % (on,))
        with self._write() as conn:
            cur = conn.execute(
                "DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?", (src, dst, format_date(on))
            )
            if cur.rowcount == 0:
                raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))

    def rate_rows(self):
        with self._read():
            return [
                (s, d, parse_date(o), t)
                for s, d, o, t in self._conn.execute(
                    "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date"
                )
            ]

    def rate_table(self):
        with self._read():
            return self._rate_table()

    def add_budget(self, budget):
        if not isinstance(budget, _budgets.Budget):
            raise ValidationError("expected a Budget, got %r" % (budget,))
        with self._write() as conn:
            if conn.execute(
                "SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?", (budget.pattern, budget.period_kind)
            ).fetchone():
                raise ConflictError("budget %s per %s already exists" % (budget.pattern, budget.period_kind))
            conn.execute(
                "INSERT INTO budgets(pattern, period_kind, minor, currency, start_date) VALUES (?, ?, ?, ?, ?)",
                (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency, format_date(budget.start)),
            )

    def remove_budget(self, pattern, period_kind):
        with self._write() as conn:
            cur = conn.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
            if cur.rowcount == 0:
                raise NotFoundError("no budget %s per %s" % (pattern, period_kind))

    def budgets(self):
        with self._read():
            rows = self._conn.execute(
                "SELECT pattern, period_kind, minor, currency, start_date FROM budgets ORDER BY pattern, period_kind"
            ).fetchall()
            return [_budgets.Budget(p, k, Money(m, c), parse_date(sd)) for p, k, m, c, sd in rows]

    @staticmethod
    def _template_json(template):
        return json.dumps(transaction_to_dict(template), sort_keys=True)

    def _recurring_rows(self):
        out = []
        for name, schedule, template, start, end, count, through in self._conn.execute(
            "SELECT name, schedule, template, start_date, end_date, max_count, materialized_through "
            "FROM recurring ORDER BY name"
        ):
            tx = transactions_from_json("[" + template + "]")[0]
            rec = _recurring.Recurring(
                name,
                schedule,
                tx,
                parse_date(start),
                parse_date(end) if end else None,
                count,
            )
            out.append((rec, parse_date(through) if through else None))
        out.sort(key=lambda item: item[0].name)
        return out

    def add_recurring(self, rec):
        if not isinstance(rec, _recurring.Recurring):
            raise ValidationError("expected a Recurring, got %r" % (rec,))
        with self._write() as conn:
            if conn.execute("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)).fetchone():
                raise ConflictError("recurring item %s already exists" % rec.name)
            conn.execute(
                "INSERT INTO recurring(name, schedule, template, start_date, end_date, max_count, materialized_through) "
                "VALUES (?, ?, ?, ?, ?, ?, NULL)",
                (
                    rec.name,
                    str(rec.schedule),
                    self._template_json(rec.template),
                    format_date(rec.start),
                    None if rec.end is None else format_date(rec.end),
                    rec.count,
                ),
            )

    def remove_recurring(self, name):
        with self._write() as conn:
            cur = conn.execute("DELETE FROM recurring WHERE name = ?", (name,))
            if cur.rowcount == 0:
                raise NotFoundError("no recurring item %s" % (name,))

    def recurring(self):
        with self._read():
            return [rec for rec, _ in self._recurring_rows()]

    def materialized_through(self, name):
        with self._read():
            row = self._conn.execute("SELECT materialized_through FROM recurring WHERE name = ?", (name,)).fetchone()
            if row is None:
                raise NotFoundError("no recurring item %s" % (name,))
            return parse_date(row[0]) if row[0] else None

    def materialize(self, upto=None, today=None):
        for value in (upto, today):
            if value is not None and not is_date(value):
                raise ValidationError("horizon must be a date, got %r" % (value,))
        if upto is None and today is None:
            raise ValidationError("materialize needs upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        with self._write() as conn:
            items = self._recurring_rows()
            pending = []
            for rec, through in items:
                first = rec.start if through is None else max(rec.start, through + timedelta(days=1))
                if first > horizon:
                    continue
                for d in _recurring.occurrences(rec, first, horizon):
                    pending.append((d, rec.name, _recurring.instantiate(rec, d)))
            pending.sort(key=lambda item: (item[0], item[1]))
            ledger = Ledger(self._chart(), self._rate_table())
            made = []
            for index, (_, _, tx) in enumerate(pending):
                try:
                    made.append(self._insert(conn, self._validated(ledger, tx)))
                except ValidationError as exc:
                    exc.detail = dict(exc.detail, index=index)
                    raise
            for rec, through in items:
                if through is None or horizon > through:
                    conn.execute(
                        "UPDATE recurring SET materialized_through = ? WHERE name = ?", (format_date(horizon), rec.name)
                    )
            return made

    # -- rules, settings, profiles ---------------------------------------
    def set_rules(self, text):
        if not isinstance(text, str):
            raise ValidationError("rules must be text")
        parse_rules(text)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rules(id, body) VALUES (1, ?)", (text,))

    def _rules_text(self):
        row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
        return "" if row is None else row[0]

    def rules_text(self):
        with self._read():
            return self._rules_text()

    def rules(self):
        return parse_rules(self.rules_text())

    def get_setting(self, key, default=None):
        with self._read():
            row = self._conn.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone()
            return default if row is None else row[0]

    def set_setting(self, key, value):
        if not isinstance(key, str) or key == "" or not isinstance(value, str):
            raise ValidationError("a setting needs a non-empty text key and a text value")
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO settings(key, value) VALUES (?, ?)", (key, value))

    def delete_setting(self, key):
        with self._write() as conn:
            conn.execute("DELETE FROM settings WHERE key = ?", (key,))

    def settings(self):
        with self._read():
            return dict(self._conn.execute("SELECT key, value FROM settings ORDER BY key").fetchall())

    @staticmethod
    def _need_profile_name(name):
        if not isinstance(name, str) or _PROFILE_NAME.fullmatch(name) is None:
            raise ValidationError("invalid profile name %r" % (name,))

    def set_profile(self, name, text):
        self._need_profile_name(name)
        if not isinstance(text, str):
            raise ValidationError("profile must be text")
        _csvimport.parse_profile(text)
        self.set_setting("profile." + name, text)

    def _profile_text(self, name):
        row = self._conn.execute("SELECT value FROM settings WHERE key = ?", ("profile." + str(name),)).fetchone()
        if row is None or not isinstance(name, str) or _PROFILE_NAME.fullmatch(name) is None:
            raise NotFoundError("no such profile: %s" % (name,))
        return row[0]

    def profile_text(self, name):
        with self._read():
            return self._profile_text(name)

    def profiles(self):
        with self._read():
            return sorted(
                k[len("profile.") :]
                for (k,) in self._conn.execute("SELECT key FROM settings WHERE key LIKE 'profile.%'")
            )

    def remove_profile(self, name):
        with self._write() as conn:
            self._profile_text(name)
            conn.execute("DELETE FROM settings WHERE key = ?", ("profile." + name,))

    # -- CSV import and journals -----------------------------------------
    def import_csv(self, text, profile, apply_rules=True):
        with self._read():
            if isinstance(profile, str):
                if _NAME_CHARS.fullmatch(profile):
                    profile = _csvimport.parse_profile(self._profile_text(profile))
                else:
                    profile = _csvimport.parse_profile(profile)
            rules = parse_rules(self._rules_text()) if apply_rules else None
            account = profile.account
            ids = [
                r[0]
                for r in self._conn.execute("SELECT DISTINCT tx_id FROM postings WHERE account = ?", (account,))
            ]
            existing = self._existing(ids)
        result = _csvimport.import_csv(text, profile, rules, existing)
        outcome = ImportOutcome([], list(result.duplicates), list(result.errors))
        if result.errors:
            return outcome
        dup_counts = {}
        for tx in result.duplicates:
            key = self._base_key(tx, account)
            dup_counts[key] = dup_counts.get(key, 0) + 1
        seen = {}
        keys = []
        for tx in result.transactions:
            base = self._base_key(tx, account)
            seen[base] = seen.get(base, 0) + 1
            keys.append("%s|%d" % (base, dup_counts.get(base, 0) + seen[base]))
        bulk = self.add_transactions(result.transactions, keys)
        outcome.added = bulk.added
        for index in bulk.skipped:
            outcome.duplicates.append(result.transactions[index])
        return outcome

    def _existing(self, ids):
        rows = []
        for i in range(0, len(ids), 500):
            chunk = ids[i : i + 500]
            rows.extend(
                self._conn.execute(
                    "SELECT id, date, payee, narration, flag FROM transactions WHERE id IN (%s)" % ",".join("?" * len(chunk)),
                    chunk,
                ).fetchall()
            )
        rows.sort(key=lambda r: (r[1], r[0]))
        return self._assemble(rows)

    @staticmethod
    def _base_key(tx, account):
        for p in tx.postings:
            if p.account == account:
                return "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, account, p.amount.minor, p.amount.currency)
        return "%s|%s|%s|" % (format_date(tx.date), tx.payee, account)

    def journal(self):
        with self._read():
            return Journal(
                [replace(a) for a in self._account_rows()],
                [
                    (s, d, parse_date(o), t)
                    for s, d, o, t in self._conn.execute(
                        "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date"
                    )
                ],
                self._assemble(self._tx_rows()),
            )

    def load_journal(self, journal):
        with self._write() as conn:
            chart = self._chart()
            rates = self._rate_table()
            for a in journal.accounts:
                added = chart.add(a.path, a.type, a.currency, a.opened, a.note)
                if a.closed is not None:
                    chart.close(a.path, a.closed)
                conn.execute(
                    "INSERT INTO accounts(path, type, currency, opened, note, closed) VALUES (?, ?, ?, ?, ?, ?)",
                    (added.path, added.type, added.currency, _d(added.opened), added.note, _d(added.closed)),
                )
            for src, dst, on, text in journal.rates:
                rates.set(src, dst, text, on)
                conn.execute(
                    "INSERT OR REPLACE INTO rates(src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                    (src, dst, format_date(on), text),
                )
            ledger = Ledger(chart, rates)
            added_txs = []
            for index, tx in enumerate(journal.transactions):
                try:
                    added_txs.append(self._insert(conn, self._validated(ledger, tx)))
                except ValidationError as exc:
                    exc.detail = dict(exc.detail, index=index)
                    raise
            return added_txs

    # -- health, backup, status ------------------------------------------
    def check(self):
        problems = []
        with self._read() as conn:
            try:
                for (line,) in conn.execute("PRAGMA integrity_check").fetchall():
                    if line != "ok":
                        problems.append("integrity check: %s" % line)
            except sqlite3.DatabaseError as exc:
                problems.append("integrity check: %s" % exc)
            queries = [
                (
                    "SELECT id, tx_id FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)",
                    "posting %d belongs to missing transaction %d",
                ),
                (
                    "SELECT rowid, tx_id FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)",
                    "tag row %d belongs to missing transaction %d",
                ),
                (
                    "SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)",
                    "import key %s belongs to missing transaction %d",
                ),
                (
                    "SELECT id, 0 FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)",
                    "transaction %d has no postings",
                ),
                (
                    "SELECT id, account FROM postings WHERE account NOT IN (SELECT path FROM accounts)",
                    "posting %d is on account %s, which is not stored",
                ),
                (
                    "SELECT tx_id, currency || ' ' || SUM(minor) FROM postings GROUP BY tx_id, currency "
                    "HAVING SUM(minor) <> 0",
                    "transaction %d does not balance: %s",
                ),
            ]
            for sql, template in queries:
                for a, b in conn.execute(sql).fetchall():
                    problems.append(template % ((a,) if "%s" not in template and template.count("%") == 1 else (a, b)))
        return sorted(problems)

    def backup(self, dest):
        self._current()
        dest = os.fspath(dest)
        if os.path.exists(dest):
            raise ConflictError("%s already exists" % dest)
        parent = os.path.dirname(os.path.abspath(dest))
        if not os.path.isdir(parent):
            raise NotFoundError("no such directory: %s" % parent)
        target = None
        try:
            target = sqlite3.connect(dest, isolation_level=None)
            self._conn.backup(target)
        except sqlite3.Error as exc:
            if target is not None:
                target.close()
            if os.path.exists(dest):
                os.remove(dest)
            raise ConflictError("backup failed: %s" % exc) from None
        target.close()

    def info(self):
        with self._read() as conn:
            counts = {
                name: conn.execute("SELECT COUNT(*) FROM %s" % table).fetchone()[0]
                for name, table in (
                    ("accounts", "accounts"),
                    ("transactions", "transactions"),
                    ("postings", "postings"),
                    ("rates", "rates"),
                    ("budgets", "budgets"),
                    ("recurring", "recurring"),
                )
            }
            return dict(path=self.path, version=self.version, **counts)


def _d(value):
    return None if value is None else format_date(value)
